#!/bin/bash
# Generated by Claude Opus 5 (Anthropic)
# campaign_final_20260909.sh — the final overhead campaign for the paper.
#
# Host state expected (scripts/host_perf_mode.sh split, already applied):
#   SMT off · turbo off · performance governor · thermald stopped
#   application  → P-cores 0,2,4,6,8,10   (FISH_APP_CPUS)
#   observer     → E-cores 12-17          (FISH_OBS_CPUS)
#   desktop      → E-cores 18-19          (user slice, AllowedCPUs)
#
# Both halves run the SAME instrumentation this time — that is the point of v8:
#   * per_instance = true  → ros2:rcl_publish + ros2:rmw_take (taken == 1)
#     (the Autoware runner already did this; the Isaac sweep did NOT, so the
#      two overhead tables were measuring different instrumentation)
#   * lean nsys profile (python/fish/nsys_flags.py, default since 2026-09-06)
#   * NO FISH_NPROC shim — proven irrelevant to the metrics on 2026-09-08 and it
#     halves the internal /clock traffic (notes/campaign_np6_2026-09-08.md)
#
# Order: Autoware 3x3 first (~75 min, also produces the session the paper
# figures are drawn from), then the Isaac sweep (13 benches, ~12 h).
set -u
cd "$(dirname "$0")/.."

STAMP=$(date +%Y%m%d_%H%M%S)
LOG=$HOME/fish_traces/campaign_final_$STAMP.log
exec >> "$LOG" 2>&1
stamp() { echo "[final $(date '+%F %T')] $*"; }

export FISH_APP_CPUS=0,2,4,6,8,10
export FISH_OBS_CPUS=12-17
export FISH_EVENT_COUNT=0

stamp "=== FINAL CAMPAIGN ==="
scripts/host_perf_mode.sh status
ip -o link show lo | grep -q MULTICAST || { stamp "ABORT: lo multicast is OFF"; exit 2; }

# ---------------------------------------------------------------- Autoware ---
stamp "--- Autoware 3x3 (baseline, lttng, nsys) ---"
IMG=autoware-dev-trt-a1000-fishwait10:latest REPS=3 MODES="baseline lttng nsys" \
    bash scripts/autoware_runs/run_overhead_modes.sh
stamp "Autoware rc=$?"
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"

# ------------------------------------------------------------------ Isaac ----
DEST_BASE=$HOME/fish_traces/overhead_isaac_final_$STAMP
export DEST_BASE
stamp "--- Isaac sweep, 13 benches x (warmup + 3 modes x 3 reps) → $DEST_BASE ---"

# external watchdog: the sweep has no per-run timeout and bi3d_freespace hung
# for 3.5 h on 2026-09-06 (notes/campaign_split_v6_incidents.md)
nohup bash scripts/run_stall_watchdog.sh "$LOG" "$DEST_BASE" 1200 60 \
      >> "$HOME/fish_traces/watchdog_final_$STAMP.log" 2>&1 &
WD=$!
stamp "watchdog pid $WD (stall 1200 s)"

REPS=3 bash scripts/overhead_sweep_v8.sh \
    apriltag bi3d bi3d_freespace dnn_image_encoder dope ess image_proc \
    nvblox segformer stereo_image_proc tensor_rt unet visual_slam
stamp "Isaac rc=$?"

kill $WD 2>/dev/null
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"
stamp "=== DONE-FINAL ==="
